CREATE TABLE TMP_PIPE_Q1 AS
SELECT "ID",
       "DATA"
FROM "COMMISSION_SALES";

ALTER TABLE TMP_PIPE_Q1 ADD CONSTRAINT q1_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q2 AS
SELECT json_transform(q."DATA",
                      SET '$."account"' = COALESCE(
                                                     (SELECT JSON_ARRAYAGG(f."DATA" RETURNING JSON)
                                                      FROM "COMMISSION_ACCOUNTS" f
                                                      WHERE f."DATA"."_id" = q."DATA".accountId), JSON_ARRAY(RETURNING JSON))) AS "DATA"
FROM
  (SELECT *
   FROM TMP_PIPE_Q1) q;

ALTER TABLE TMP_PIPE_Q2 ADD CONSTRAINT q2_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q3 AS
SELECT json_transform(q."DATA",
                      SET '$."account"' = jt.elem) AS "DATA"
FROM TMP_PIPE_Q2 q,
     JSON_TABLE(q."DATA", '$.account[*]' COLUMNS (elem JSON PATH '$')) jt;

ALTER TABLE TMP_PIPE_Q3 ADD CONSTRAINT q3_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q4 AS
SELECT json_transform(q."DATA",
                      SET '$."salesRep"' = COALESCE(
                                                      (SELECT JSON_ARRAYAGG(f."DATA" RETURNING JSON)
                                                       FROM "SALES_REPS" f
                                                       WHERE f."DATA"."_id" = q."DATA".salesRepId), JSON_ARRAY(RETURNING JSON))) AS "DATA"
FROM
  (SELECT *
   FROM TMP_PIPE_Q3) q;

ALTER TABLE TMP_PIPE_Q4 ADD CONSTRAINT q4_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q5 AS
SELECT json_transform(q."DATA",
                      SET '$."salesRep"' = jt.elem) AS "DATA"
FROM TMP_PIPE_Q4 q,
     JSON_TABLE(q."DATA", '$.salesRep[*]' COLUMNS (elem JSON PATH '$')) jt;

ALTER TABLE TMP_PIPE_Q5 ADD CONSTRAINT q5_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q6 AS
SELECT json_transform(q."DATA",
                      SET '$."schedule"' = COALESCE(
                                                      (SELECT JSON_ARRAYAGG(f."DATA" RETURNING JSON)
                                                       FROM "COMMISSION_SCHEDULE" f
                                                       WHERE (JSON_VALUE(f."DATA", '$.accountType') = JSON_VALUE(q."DATA", '$.account.accountType')
                                                              AND JSON_VALUE(f."DATA", '$.effectiveDate') <= JSON_VALUE(q."DATA", '$.saleDate')
                                                              AND (JSON_VALUE(f."DATA", '$.expirationDate') IS NULL
                                                                   OR JSON_VALUE(f."DATA", '$.expirationDate') >= JSON_VALUE(q."DATA", '$.saleDate')))), JSON_ARRAY(RETURNING JSON))) AS "DATA"
FROM
  (SELECT *
   FROM TMP_PIPE_Q5) q;

ALTER TABLE TMP_PIPE_Q6 ADD CONSTRAINT q6_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q7 AS
SELECT json_transform(q."DATA",
                      SET '$."schedule"' = jt.elem) AS "DATA"
FROM TMP_PIPE_Q6 q,
     JSON_TABLE(q."DATA", '$.schedule[*]' COLUMNS (elem JSON PATH '$')) jt;

ALTER TABLE TMP_PIPE_Q7 ADD CONSTRAINT q7_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q8 AS
SELECT json_transform("DATA",
                      SET '$."productMultiplier"' = COALESCE(get_dynamic_json_field("DATA", '$.schedule.productMultipliers', '$.productCategory'), JSON('1')),
                      SET '$."dealTypeMultiplier"' = COALESCE(get_dynamic_json_field("DATA", '$.schedule.dealTypeMultipliers', '$.dealType'), JSON('1'))) AS "DATA"
FROM TMP_PIPE_Q7 q;

ALTER TABLE TMP_PIPE_Q8 ADD CONSTRAINT q8_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q9 AS
SELECT json_transform("DATA",
                      SET '$."adjustedAmount"' = (JSON_VALUE("DATA", '$.amount' RETURNING NUMBER) * JSON_VALUE("DATA", '$.productMultiplier' RETURNING NUMBER) * JSON_VALUE("DATA", '$.dealTypeMultiplier' RETURNING NUMBER))) AS "DATA"
FROM TMP_PIPE_Q8 q;

ALTER TABLE TMP_PIPE_Q9 ADD CONSTRAINT q9_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q10 AS
SELECT JSON_OBJECT('_id' VALUE JSON_OBJECT('salesRepId' VALUE JSON_QUERY("DATA", '$.salesRepId'), 'accountType' VALUE JSON_QUERY("DATA", '$.account.accountType')), 'salesRep' VALUE MIN(q."DATA".salesRep), 'accountType' VALUE MIN(q."DATA".account.accountType), 'schedule' VALUE MIN(q."DATA".schedule), 'totalSalesAmount' VALUE SUM(q."DATA".amount), 'totalAdjustedAmount' VALUE SUM(q."DATA".adjustedAmount), 'dealCount' VALUE SUM(1), 'salesByProduct' VALUE JSON_ARRAYAGG(JSON_OBJECT('category' VALUE JSON_QUERY("DATA", '$.productCategory'), 'amount' VALUE JSON_QUERY("DATA", '$.amount')) RETURNING JSON), 'accountsSold' VALUE JSON_QUERY('["' || LISTAGG(DISTINCT JSON_OBJECT('accountId' VALUE JSON_QUERY("DATA", '$.accountId'), 'industrySector' VALUE JSON_QUERY("DATA", '$.account.industrySector')), '","') WITHIN GROUP (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ORDER BY JSON_OBJECT('accountId' VALUE JSON_QUERY("DATA", '$.accountId'), 'industrySector' VALUE JSON_QUERY("DATA", '$.account.industrySector'))) || '"]', '$' RETURNING JSON)) AS "DATA"
FROM
  (SELECT *
   FROM TMP_PIPE_Q9) q
GROUP BY JSON_QUERY("DATA", '$.salesRepId'),
         JSON_QUERY("DATA", '$.account.accountType');

ALTER TABLE TMP_PIPE_Q10 ADD CONSTRAINT q10_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q11 AS
SELECT json_transform("DATA",
                      SET '$."applicableTier"' =
                        (SELECT jt.tier_data
                         FROM JSON_TABLE("DATA", '$.schedule.tiers[*]' COLUMNS (jt_minVolume NUMBER PATH '$.minVolume', jt_maxVolume NUMBER PATH '$.maxVolume', tier_data JSON PATH '$')) jt
                         WHERE (q."DATA".totalAdjustedAmount >= jt.jt_minVolume
                                AND q."DATA".totalAdjustedAmount < jt.jt_maxVolume) FETCH FIRST 1 ROW ONLY)) AS "DATA"
FROM TMP_PIPE_Q10 q;

ALTER TABLE TMP_PIPE_Q11 ADD CONSTRAINT q11_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q12 AS
SELECT json_transform("DATA",
                      SET '$."quarterlyQuota"' = JSON_QUERY("DATA", '$.salesRep.quota.quarterly'),
                      SET '$."quotaAttainment"' = CASE
                                                      WHEN q."DATA".salesRep.quota.quarterly > 0 THEN (JSON_VALUE("DATA", '$.totalSalesAmount' RETURNING NUMBER) / JSON_VALUE("DATA", '$.salesRep.quota.quarterly' RETURNING NUMBER))
                                                      ELSE 0
                                                  END) AS "DATA"
FROM TMP_PIPE_Q11 q;

ALTER TABLE TMP_PIPE_Q12 ADD CONSTRAINT q12_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q13 AS
SELECT json_transform("DATA",
                      SET '$."effectiveAccelerator"' = CASE
                                                           WHEN q."DATA".quotaAttainment > 1 THEN JSON_QUERY("DATA", '$.applicableTier.accelerator')
                                                           ELSE '1'
                                                       END) AS "DATA"
FROM TMP_PIPE_Q12 q;

ALTER TABLE TMP_PIPE_Q13 ADD CONSTRAINT q13_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q14 AS
SELECT json_transform("DATA",
                      SET '$."commissionRate"' = JSON_QUERY("DATA", '$.applicableTier.baseRate'),
                      SET '$."baseCommission"' = (JSON_VALUE("DATA", '$.totalAdjustedAmount' RETURNING NUMBER) * JSON_VALUE("DATA", '$.applicableTier.baseRate' RETURNING NUMBER))) AS "DATA"
FROM TMP_PIPE_Q13 q;

ALTER TABLE TMP_PIPE_Q14 ADD CONSTRAINT q14_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q15 AS
SELECT json_transform("DATA",
                      SET '$."finalCommission"' = (JSON_VALUE("DATA", '$.baseCommission' RETURNING NUMBER) * JSON_VALUE("DATA", '$.effectiveAccelerator' RETURNING NUMBER)),
                      SET '$."acceleratorBonus"' = ((JSON_VALUE("DATA", '$.baseCommission' RETURNING NUMBER) * JSON_VALUE("DATA", '$.effectiveAccelerator' RETURNING NUMBER)) - JSON_VALUE("DATA", '$.baseCommission' RETURNING NUMBER))) AS "DATA"
FROM TMP_PIPE_Q14 q;

ALTER TABLE TMP_PIPE_Q15 ADD CONSTRAINT q15_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q16 AS
SELECT json_transform("DATA",
                      SET '$."productBreakdown"' = JSON_OBJECT('software' VALUE
                                                                 (SELECT NVL(SUM(CASE
                                                                                     WHEN jt_category = 'software' THEN jt_amount
                                                                                     ELSE 0
                                                                                 END), 0)
                                                                  FROM JSON_TABLE("DATA", '$.salesByProduct[*]' COLUMNS (jt_category VARCHAR2(4000) PATH '$.category', jt_amount NUMBER PATH '$.amount'))), 'hardware' VALUE
                                                                 (SELECT NVL(SUM(CASE
                                                                                     WHEN jt_category = 'hardware' THEN jt_amount
                                                                                     ELSE 0
                                                                                 END), 0)
                                                                  FROM JSON_TABLE("DATA", '$.salesByProduct[*]' COLUMNS (jt_category VARCHAR2(4000) PATH '$.category', jt_amount NUMBER PATH '$.amount'))), 'services' VALUE
                                                                 (SELECT NVL(SUM(CASE
                                                                                     WHEN jt_category = 'services' THEN jt_amount
                                                                                     ELSE 0
                                                                                 END), 0)
                                                                  FROM JSON_TABLE("DATA", '$.salesByProduct[*]' COLUMNS (jt_category VARCHAR2(4000) PATH '$.category', jt_amount NUMBER PATH '$.amount'))), 'support' VALUE
                                                                 (SELECT NVL(SUM(CASE
                                                                                     WHEN jt_category = 'support' THEN jt_amount
                                                                                     ELSE 0
                                                                                 END), 0)
                                                                  FROM JSON_TABLE("DATA", '$.salesByProduct[*]' COLUMNS (jt_category VARCHAR2(4000) PATH '$.category', jt_amount NUMBER PATH '$.amount'))))) AS "DATA"
FROM TMP_PIPE_Q15 q;

ALTER TABLE TMP_PIPE_Q16 ADD CONSTRAINT q16_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q17 AS
SELECT JSON_OBJECT('_id' VALUE q."DATA".salesRep."_id", 'salesRepName' VALUE MIN(NULL), 'salesRepTier' VALUE MIN(q."DATA".salesRep.tier), 'region' VALUE MIN(q."DATA".salesRep.region), 'territory' VALUE MIN(q."DATA".salesRep.territory), 'quarterlyQuota' VALUE MIN(q."DATA".salesRep.quota.quarterly), 'totalSalesAmount' VALUE SUM(q."DATA".totalSalesAmount), 'totalAdjustedAmount' VALUE SUM(q."DATA".totalAdjustedAmount), 'totalCommission' VALUE SUM(q."DATA".finalCommission), 'totalAcceleratorBonus' VALUE SUM(q."DATA".acceleratorBonus), 'totalDealCount' VALUE SUM(q."DATA".dealCount), 'commissionByAccountType' VALUE JSON_ARRAYAGG(JSON_OBJECT('accountType' VALUE JSON_QUERY("DATA", '$.accountType'), 'salesAmount' VALUE JSON_QUERY("DATA", '$.totalSalesAmount'), 'adjustedAmount' VALUE JSON_QUERY("DATA", '$.totalAdjustedAmount'), 'commission' VALUE JSON_QUERY("DATA", '$.finalCommission'), 'tier' VALUE JSON_QUERY("DATA", '$.applicableTier.tierName'), 'rate' VALUE JSON_QUERY("DATA", '$.commissionRate'), 'dealCount' VALUE JSON_QUERY("DATA", '$.dealCount')) RETURNING JSON), 'productBreakdowns' VALUE JSON_ARRAYAGG(JSON_QUERY("DATA", '$.productBreakdown') RETURNING JSON), 'accountsSold' VALUE JSON_ARRAYAGG(JSON_QUERY("DATA", '$.accountsSold') RETURNING JSON)) AS "DATA"
FROM
  (SELECT *
   FROM TMP_PIPE_Q16) q
GROUP BY q."DATA".salesRep."_id";

ALTER TABLE TMP_PIPE_Q17 ADD CONSTRAINT q17_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q18 AS
SELECT json_transform("DATA",
                      SET '$."productSummary"' = JSON_OBJECT('software' VALUE
                                                               (SELECT NVL(SUM(jt_software), 0)
                                                                FROM JSON_TABLE("DATA", '$.productBreakdowns[*]' COLUMNS (jt_software VARCHAR2(4000) PATH '$.software'))), 'hardware' VALUE
                                                               (SELECT NVL(SUM(jt_hardware), 0)
                                                                FROM JSON_TABLE("DATA", '$.productBreakdowns[*]' COLUMNS (jt_hardware VARCHAR2(4000) PATH '$.hardware'))), 'services' VALUE
                                                               (SELECT NVL(SUM(jt_services), 0)
                                                                FROM JSON_TABLE("DATA", '$.productBreakdowns[*]' COLUMNS (jt_services VARCHAR2(4000) PATH '$.services'))), 'support' VALUE
                                                               (SELECT NVL(SUM(jt_support), 0)
                                                                FROM JSON_TABLE("DATA", '$.productBreakdowns[*]' COLUMNS (jt_support VARCHAR2(4000) PATH '$.support')))),
                      SET '$."uniqueAccounts"' =
                        (SELECT JSON_ARRAYAGG(val RETURNING JSON)
                         FROM
                           (SELECT DISTINCT val
                            FROM JSON_TABLE("DATA", '$.accountsSold[*][*]' COLUMNS (val JSON PATH '$')))),
                      SET '$."quotaAttainment"' = CASE
                                                      WHEN q."DATA".quarterlyQuota > 0 THEN (JSON_VALUE("DATA", '$.totalSalesAmount' RETURNING NUMBER) / JSON_VALUE("DATA", '$.quarterlyQuota' RETURNING NUMBER))
                                                      ELSE 0
                                                  END) AS "DATA"
FROM TMP_PIPE_Q17 q;

ALTER TABLE TMP_PIPE_Q18 ADD CONSTRAINT q18_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q19 AS
SELECT json_transform("DATA",
                      SET '$."industrySectors"' =
                        (SELECT JSON_ARRAYAGG(val)
                         FROM
                           (SELECT DISTINCT val
                            FROM
                              (SELECT val
                               FROM JSON_TABLE(
                                                 (SELECT COALESCE(JSON_ARRAYAGG(industrySector), JSON_ARRAY())
                                                  FROM JSON_TABLE("DATA", '$.uniqueAccounts[*]' COLUMNS (industrySector VARCHAR2(4000) PATH '$.industrySector'))), '$[*]' COLUMNS (val VARCHAR2(4000) PATH '$')))))) AS "DATA"
FROM TMP_PIPE_Q18 q;

ALTER TABLE TMP_PIPE_Q19 ADD CONSTRAINT q19_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q20 AS
SELECT json_transform("DATA",
                      SET '$."salesRepId"' = JSON_QUERY("DATA", '$._id'),
                      SET '$."metrics"' = JSON_OBJECT('totalSales' VALUE ROUND(JSON_VALUE("DATA", '$.totalSalesAmount' RETURNING NUMBER), 2), 'adjustedSales' VALUE ROUND(JSON_VALUE("DATA", '$.totalAdjustedAmount' RETURNING NUMBER), 2), 'quota' VALUE ROUND(JSON_VALUE("DATA", '$.quarterlyQuota' RETURNING NUMBER), 2), 'quotaAttainment' VALUE ROUND((JSON_VALUE("DATA", '$.quotaAttainment' RETURNING NUMBER) * 100), 1), 'dealCount' VALUE JSON_QUERY("DATA", '$.totalDealCount'), 'uniqueAccountsCount' VALUE JSON_VALUE("DATA", '$.uniqueAccounts.size()' RETURNING NUMBER)),
                      SET '$."commission"' = JSON_OBJECT('total' VALUE ROUND(JSON_VALUE("DATA", '$.totalCommission' RETURNING NUMBER), 2), 'acceleratorBonus' VALUE ROUND(JSON_VALUE("DATA", '$.totalAcceleratorBonus' RETURNING NUMBER), 2), 'effectiveRate' VALUE ROUND(((JSON_VALUE("DATA", '$.totalCommission' RETURNING NUMBER) / JSON_VALUE("DATA", '$.totalAdjustedAmount' RETURNING NUMBER)) * 100), 2), 'byAccountType' VALUE JSON_QUERY("DATA", '$.commissionByAccountType')), KEEP '$."salesRepName"', '$."salesRepTier"', '$."region"', '$."territory"', '$."productSummary"', '$."industrySectors"', '$."salesRepId"', '$."metrics"', '$."commission"') AS "DATA"
FROM TMP_PIPE_Q19 q;

ALTER TABLE TMP_PIPE_Q20 ADD CONSTRAINT q20_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q21_byRep AS
SELECT "DATA" AS "DATA"
FROM TMP_PIPE_Q20 q
ORDER BY JSON_VALUE(q."DATA", '$.commission.total' RETURNING NUMBER NULL ON ERROR) DESC NULLS LAST, JSON_VALUE(q."DATA", '$.commission.total') DESC NULLS LAST;

ALTER TABLE TMP_PIPE_Q21_byRep ADD CONSTRAINT q21_byrep_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q21_byRegion AS
SELECT "DATA" AS "DATA"
FROM
  (SELECT JSON_OBJECT('_id' VALUE q."DATA".region, 'totalSales' VALUE SUM(q."DATA".metrics.totalSales), 'totalCommission' VALUE SUM(q."DATA".commission.total), 'totalQuota' VALUE SUM(q."DATA".metrics.quota), 'repCount' VALUE SUM(1), 'avgQuotaAttainment' VALUE AVG(q."DATA".metrics.quotaAttainment), 'dealCount' VALUE SUM(q."DATA".metrics.dealCount), 'reps' VALUE JSON_ARRAYAGG(JSON_OBJECT('name' VALUE JSON_QUERY("DATA", '$.salesRepName'), 'sales' VALUE JSON_QUERY("DATA", '$.metrics.totalSales'), 'commission' VALUE JSON_QUERY("DATA", '$.commission.total'), 'quotaAttainment' VALUE JSON_QUERY("DATA", '$.metrics.quotaAttainment')) RETURNING JSON)) AS "DATA"
   FROM TMP_PIPE_Q20 q
   GROUP BY q."DATA".region)
ORDER BY JSON_VALUE("DATA", '$.totalSales') DESC;

ALTER TABLE TMP_PIPE_Q21_byRegion ADD CONSTRAINT q21_byregion_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q21_totals AS
SELECT JSON_OBJECT('_id' VALUE NULL, 'grandTotalSales' VALUE SUM(q."DATA".metrics.totalSales), 'grandTotalCommission' VALUE SUM(q."DATA".commission.total), 'grandTotalQuota' VALUE SUM(q."DATA".metrics.quota), 'totalReps' VALUE SUM(1), 'totalDeals' VALUE SUM(q."DATA".metrics.dealCount), 'avgQuotaAttainment' VALUE AVG(q."DATA".metrics.quotaAttainment)) AS "DATA"
FROM TMP_PIPE_Q20 q;

ALTER TABLE TMP_PIPE_Q21_totals ADD CONSTRAINT q21_totals_json CHECK ("DATA" IS JSON);

CREATE TABLE TMP_PIPE_Q21 AS
SELECT JSON_OBJECT('byRep' VALUE COALESCE(
                                            (SELECT JSON_ARRAYAGG("DATA" RETURNING JSON)
                                             FROM TMP_PIPE_Q21_byRep), JSON_ARRAY(RETURNING JSON)), 'byRegion' VALUE COALESCE(
                                                                                                                                (SELECT JSON_ARRAYAGG("DATA" RETURNING JSON)
                                                                                                                                 FROM TMP_PIPE_Q21_byRegion), JSON_ARRAY(RETURNING JSON)), 'totals' VALUE COALESCE(
                                                                                                                                                                                                                     (SELECT JSON_ARRAYAGG("DATA" RETURNING JSON)
                                                                                                                                                                                                                      FROM TMP_PIPE_Q21_totals), JSON_ARRAY(RETURNING JSON))) AS "DATA"
FROM DUAL;

ALTER TABLE TMP_PIPE_Q21 ADD CONSTRAINT q21_json CHECK ("DATA" IS JSON);

SELECT JSON_ARRAYAGG("DATA" RETURNING CLOB)
FROM TMP_PIPE_Q21;

